          'post.js',
          'file_write({path: "$log", content: params.ticket.key});',
        );
        await (CliAgent(
          params: CliAgentParams()
            ..cliCommands = ['echo done']
            ..postJSAction = js.path
            ..cleanupInputFolder = false,
          workingDirectory: tmp.path,
          ticketData: const {
            'key': 'GH-21',
