private void executeJsAction(String action, String actionName, CliAgentParams params, String response,
                              String inputFolderPath, ITicket ticket) {
    if (action == null || action.trim().isEmpty()) {
        return;
    }
    try {
        logger.info("Executing {}: {}", actionName, action);
        Map<String, Object> extraBindings = new HashMap<>();
        if (inputFolderPath != null) {
            extraBindings.put("inputFolderPath", inputFolderPath);
        }
        if (ticket != null) {
            extraBindings.put("ticket", ticket);
        }
        prepareJsExecutor(action, params, response, extraBindings.isEmpty() ? null : extraBindings, ticket)
                .execute();
    } catch (Exception e) {
        logger.warn("{} failed, continuing: {}", actionName, e.getMessage(), e);
    }
}

private void executeScriptHook(String script, String hookName, CliAgentParams params, Path workingDirectory,
                                String response) {
    if (script == null || script.trim().isEmpty()) {
        return;
    }
    logger.info("Executing {} hook: {}", hookName, script);
    try {
        if (script.endsWith(".js")) {
            Map<String, Object> extraBindings = Collections.singletonMap(
                    "workingDirectory", workingDirectory.toAbsolutePath().toString());
            prepareJsExecutor(script, params, response, extraBindings, null).execute();
        } else {
            CommandLineUtils.runCommand(script, workingDirectory.toFile(), PropertyReader.getOverrides(), null, false);
        }
    } catch (Exception e) {
        // e.getMessage() no longer carries the raw output for CliCommandFailedException — getDiagnosticMessage() does.
        String msg = e instanceof CliCommandFailedException
                ? ((CliCommandFailedException) e).getDiagnosticMessage()
                : e.getMessage();
        logger.warn("{} hook failed, continuing: {}", hookName, msg, e);
    }
}

private Runnable buildTimerRunnable(CliAgentParams params, AtomicReference<String> liveOutput) {
    String timerJSAction = params.getTimerJSAction();
    if (timerJSAction == null || timerJSAction.trim().isEmpty()) {
        return null;
    }
    return () -> {
        try {
            logger.info("Executing timerJSAction: {}", timerJSAction);
            Map<String, Object> extraBindings = Collections.singletonMap(
                    "currentCliOutput", liveOutput.get());
            prepareJsExecutor(timerJSAction, params, null, extraBindings, null).execute();
        } catch (Exception e) {
            logger.warn("timerJSAction execution failed (CLI continues): {}", e.getMessage(), e);
        }
    };
}

private Consumer<Exception> buildErrorHandler(CliAgentParams params, AtomicReference<String> liveOutput) {
    String cliExecutionErrorJSAction = params.getCliExecutionErrorJSAction();
    if (cliExecutionErrorJSAction == null || cliExecutionErrorJSAction.trim().isEmpty()) {
        return null;
    }
    return exception -> {
        try {
            logger.info("Executing cliExecutionErrorJSAction: {}", cliExecutionErrorJSAction);
            Map<String, Object> extraBindings = new HashMap<>();
            extraBindings.put("errorMessage", exception.getMessage());
            extraBindings.put("currentCliOutput", liveOutput.get());
            prepareJsExecutor(cliExecutionErrorJSAction, params, null, extraBindings, null).execute();
        } catch (Exception e) {
            logger.warn("cliExecutionErrorJSAction execution failed: {}", e.getMessage(), e);
        }
    };
}

private Predicate<String> buildLineStopPredicate(CliAgentParams params, AtomicReference<String> liveOutput) {
    String cliOutputLineJSAction = params.getCliOutputLineJSAction();
    if (cliOutputLineJSAction == null || cliOutputLineJSAction.trim().isEmpty()) {
        return null;
    }
    return line -> {
        try {
            logger.debug("Executing cliOutputLineJSAction for line: {}", line);
            Map<String, Object> extraBindings = new HashMap<>();
            extraBindings.put("line", line);
            extraBindings.put("currentCliOutput", liveOutput.get());
            Object result = prepareJsExecutor(cliOutputLineJSAction, params, null, extraBindings, null).execute();
            boolean stop = result != null && Boolean.parseBoolean(String.valueOf(result));
            if (stop) {
                logger.info("cliOutputLineJSAction requested stop at line: {}", line);
            }
            return stop;
        } catch (Exception e) {
            logger.warn("cliOutputLineJSAction execution failed for line (continuing): {}", e.getMessage(), e);
            return false;
        }
    };
}

private void cleanupOutputsFolder(Path workingDirectory) throws IOException {
    Path outputFolder = workingDirectory.resolve("outputs");
    Path legacyOutputFolder = workingDirectory.resolve("output");
    if (Files.exists(outputFolder)) {
        FileUtils.deleteDirectory(outputFolder.toFile());
        logger.info("Cleaned up outputs folder: {}", outputFolder.toAbsolutePath());
    }

    if (Files.exists(legacyOutputFolder)) {
        FileUtils.deleteDirectory(legacyOutputFolder.toFile());
        logger.info("Cleaned up legacy output folder: {}", legacyOutputFolder.toAbsolutePath());
    }
}

private void clearStaleOutputResponses(Path workingDirectory) throws IOException {
    Files.deleteIfExists(workingDirectory.resolve("outputs").resolve("response.md"));
    Files.deleteIfExists(workingDirectory.resolve("output").resolve("response.md"));
}

private void ensureOutputFolder(Path workingDirectory) throws IOException {
    Path outputFolder = workingDirectory.resolve("outputs");
    Files.createDirectories(outputFolder);

