    test('timerJSAction sees params.metadata.contextId', () async {
      final tmp = await _createTempDir();
      final log = '${tmp.path}/js_timer_meta.log';
      try {
        final js = _actionJs(
          tmp,
          'timer_meta.js',
          'file_write({path: "$log", content: params.metadata.contextId});',
