    this.ai = ai;
    this.confluence = confluence;
    this.sourceCode = sourceCode;
    return this;
}

/**
 * Configure MCP clients including KB tools for JavaScript execution
 */
public JavaScriptExecutor mcpWithKB(TrackerClient<?> trackerClient, AI ai, Confluence confluence, SourceCode sourceCode, com.github.istin.dmtools.common.kb.tool.KBTools kbTools) {
    this.trackerClient = trackerClient;
    this.ai = ai;
    this.confluence = confluence;
    this.sourceCode = sourceCode;
    this.kbTools = kbTools;
    return this;
}

/**
 * Add job context parameters (jobParams, ticket, response)
 */
public JavaScriptExecutor withJobContext(Object jobParams, Object ticket, Object response) {
    this.parameters.put("jobParams", jobParams);
    this.parameters.put("ticket", ticket);
    this.parameters.put("response", response);
    return this;
}

/**
 * Add a custom parameter
 */
public JavaScriptExecutor with(String key, Object value) {
    this.parameters.put(key, value);
    return this;
