void main() {
  lifecycleJsActionTests();
  ticketContextJsActionTests();
  metadataBindingJsActionTests();
  metadataContextHooksJsActionTests();
  metadataOmissionJsActionTests();
  timerJsActionTests();
  cliErrorJsActionTests();
  cliOutputLineJsActionTests();
