void lifecycleJsActionTests() {
  group('CliAgent JS actions', () {
    test('setup .js hook is executed via JsJobRunner', () async {
      final tmp = await _createTempDir();
      final log = '${tmp.path}/js_setup.log';
      try {
        final js = _actionJs(
