    final cfg = config ?? const JsRunConfig();
    final rt = QuickjsRuntime();
    try {
      final reg = cfg.registry ?? createDefaultToolRegistry();
      final compat =
          _wireRuntime(rt, reg, jobParams, ticket, workingDirectory, cfg);
