  final md = params['metadata'];
  if (md is Map) {
    final contextId = md['contextId'];
    if (contextId is String && contextId.isNotEmpty) return '[$contextId] ';
    final agentId = md['agentId'];
    if (agentId is String && agentId.isNotEmpty) return '[$agentId] ';
  }
  return '';
}

