          'pre_cli_meta.js',
          'file_write({path: "$log", content: params.metadata.contextId});',
        );
        await (CliAgent(
          params: CliAgentParams()
            ..cliCommands = ['echo done']
            ..metadata = const {'contextId': 'gh-317', 'agentId': 'senior'}
            ..preCliJSAction = js.path
