              '+ "\\n"});',
        );
        final post = _actionJs(
          tmp,
          'post_meta.js',
          'file_append({path: "$log", content: "post=" + '
              'params.metadata.contextId + ":" + params.metadata.agentId '
              '+ "\\n"});',
        );
        await (CliAgent(
          params: CliAgentParams()
