/// pinned to the ticket key (Java Teammate's input folder is
/// `input/<ticketKey>/`).
CliAgentParams _paramsForTicket(String key) {
  final p = CliAgentParams.fromJson(params);
  p.metadata = {...?p.metadata, 'contextId': key};
  return p;
